-- V144: server-created VNPay checkout of a ticket-folio VNPAY collection (003.3 T108, FR-031, FR-049).
-- The merchant reference (external_reference) is now generated by the server, never taken from the client. The
-- collection keeps the checkout URL while the attempt can still be paid, when the URL stops working, and the
-- immutable VNPay create date that QueryDR needs to reconcile the part (T109). Rows written before this
-- migration keep NULL: they have no URL to show and no create date to query by.
ALTER TABLE settlement_folio_collections
    ADD COLUMN payment_url_snapshot VARCHAR(2048) NULL DEFAULT NULL,
    ADD COLUMN payment_expires_at DATETIME(6) NULL DEFAULT NULL,
    ADD COLUMN provider_create_date CHAR(14) NULL DEFAULT NULL;
